mapper.select:
SELECT * FROM health_vital_signs
WHERE user_id = #{userId} AND type = #{type}
ORDER BY create_time DESC
LIMIT #{limit}

SELECT * FROM health_vital_signs
WHERE user_id = #{userId} AND create_time BETWEEN #{startTime} AND #{endTime}
ORDER BY create_time ASC

SELECT h.* FROM health_vital_signs h INNER JOIN ( SELECT user_id, type, MAX(create_time) as max_time FROM health_vital_signs WHERE user_id = #{userId} AND type IN
#{type}
GROUP BY user_id, type ) latest ON h.user_id = latest.user_id AND h.type = latest.type AND h.create_time = latest.max_time
